// TH15 st04.ecl.txt MainSub01:960-1012
// Three mirrored laser-fan groups; every fan comes from ECir01:105-139 (entry/drift)
// and ECir01_at:141-175 (fan + laser EX WAIT 60 / ACCEL 120 r=0.1).
// Source line 960 is local frame 0; the shell's 120-frame opening buffer precedes it.

const TIME_LIMIT: int = 1424;
const OPENING_BUFFER: int = 120;

// laserNew(0, 0, 128, 0, 16): Line judgement segment = [0.1L, 0.9L],
// width w=16 -> half-height 4 -> target width 8.
const LASER_FAR: fx = 115.2fx;
const LASER_NEAR: fx = 12.8fx;
const LASER_WIDTH: fx = 8fx;
const LASER_COLOR: int = 4;

// Fan laser handles live in the globals free segment, one 20-slot block per fan.
const FAN_SLOT_BASE: int = 16;
const FAN_STRIDE: int = 20;

// ECir01_at: B = diffI(10, 20, 20, 20) shots; after each laserOn the source
// waits 10 (Easy) or 5 frames and subtracts F1 from the base angle (twice on Easy).
// Each laser carries WAIT 60 then ACCEL 120 with r=0.1 along its own angle, so the
// rod slides out at 0.4 px/frame and then 0.4 + 0.1*(age-60) for 120 frames.
// Judgement geometry is held at the full Line segment: the source grows the line
// from 0 to 128 px first and only collides once L>16 (~40 frames at 0.4 px/frame),
// so warn=40 reproduces that activation delay; the 0..128 px growth itself is
// approximated by the full [12.8, 115.2] rod (see report).
async sub laser_fan(f0: angle, step: angle, gap: int, count: int, slot0: int) {
    var bx: fx = $self_x;
    var by: fx = $self_y;
    var a: angle = aim_player() + f0;
    var t: int = 0;
    var k: int = 0;
    var next: int = 0;
    var stop: int = (count - 1) * gap + 220;
    for i in 0..FAN_STRIDE { set_global(slot0 + i, -1); }
    loop {
        if t == next && k < count {
            var lz: int = laser(LASER_COLOR, bx, by, a, LASER_FAR, LASER_WIDTH, 40, 400, 0);
            lz_start(lz, LASER_NEAR);
            set_global(slot0 + k, lz);
            k = k + 1;
            a = a - step;
            next = next + gap;
        }
        for j in 0..FAN_STRIDE {
            var h: int = global(slot0 + j);
            if lz_alive(h) == 1 {
                var age: int = t - j * gap;
                if age >= 0 {
                    var sv: fx = 0fx;
                    if age <= 60 {
                        sv = (age as fx) * 0.4fx;
                    } else {
                        var x: fx = (age - 60) as fx;
                        sv = 24fx + x * 0.4fx + x * x * 0.05fx;
                    }
                    var d: fx = sv - 128fx;
                    if d < 0fx { d = 0fx; }
                    var an: angle = lz_angle(h);
                    lz_origin(h, bx + d * cos(an), by + d * sin(an));
                    if d > 547fx { lz_cancel(h); }
                }
            }
        }
        if t > stop { return; }
        t = t + 1;
        wait(1);
    }
}

// ECir01: movePosRel(-64,-128) + movePosRelTime(60, quad-out, 0, 0) entrance,
// flagSet(15)/flagClear(15) around the 60-frame entry (body collision off),
// then the async fan, then moveVel(ANGLE_PLAYER, 0) and moveSpeedTime(120, 0, 1).
async sub emitter(cx: fx, cy: fx, f0: angle, step: angle, gap: int, count: int, slot0: int) {
    set_invuln(65535);
    set_hitbox(8fx);          // setHitbox(16,16) -> r=8
    set_hurtbox(12fx);        // setHurtbox(24,24) -> r=12
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(60, cx, cy, EASE_QUAD_OUT);
    wait(60);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn laser_fan(f0, step, gap, count, slot0);
    wait(180);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);
    move_speed(120, 1fx, EASE_LINEAR);
    loop { wait(1000); }
}

// enmCreate places the child at parent + (x, y); the entry offset is folded into
// the spawn point so the quad-out glide ends exactly on the source create point.
sub spawn_emitter(cx: fx, cy: fx, f0: angle, step: angle, gap: int, count: int, slot: int, hp: int) {
    _ = spawn_enemy(cx - 64fx, cy - 128fx, hp, 0, 1000, 0,
                    emitter(cx, cy, f0, step, gap, count, slot));
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var count: int = 20;
    var gap: int = 5;
    var s10: angle = 10deg;
    var s8: angle = 8deg;
    var s6: angle = 6deg;
    if global(GVAR_RANK) == RANK_EASY {
        count = 10;
        gap = 10;
        s10 = 20deg;      // Easy subtracts F1 twice per shot
        s8 = 16deg;
        s6 = 12deg;
    }
    // group 1 (source 960-974): F0 = +-90deg, F1 = +-10deg
    spawn_emitter(-128fx, 128fx, 90deg, s10, gap, count, FAN_SLOT_BASE + 0 * FAN_STRIDE, 400);
    if global(GVAR_RANK) >= RANK_HARD {
        spawn_emitter(32fx, 32fx, 90deg, s10, gap, count, FAN_SLOT_BASE + 1 * FAN_STRIDE, 200);
    }
    spawn_emitter(128fx, 128fx, 0deg - 90deg, 0deg - s10, gap, count, FAN_SLOT_BASE + 2 * FAN_STRIDE, 400);
    if global(GVAR_RANK) >= RANK_HARD {
        spawn_emitter(-32fx, 32fx, 0deg - 90deg, 0deg - s10, gap, count, FAN_SLOT_BASE + 3 * FAN_STRIDE, 200);
    }
    wait(150);
    // group 2 (source 975-992): F0 = +-90deg, F1 = +-8deg;
    // Lunatic side emitter (80,0) with F0 = -40deg, F1 = -10deg
    spawn_emitter(-128fx, 128fx, 90deg, s8, gap, count, FAN_SLOT_BASE + 4 * FAN_STRIDE, 400);
    if global(GVAR_RANK) >= RANK_HARD {
        spawn_emitter(32fx, 32fx, 90deg, s8, gap, count, FAN_SLOT_BASE + 5 * FAN_STRIDE, 200);
    }
    spawn_emitter(128fx, 128fx, 0deg - 90deg, 0deg - s8, gap, count, FAN_SLOT_BASE + 6 * FAN_STRIDE, 400);
    if global(GVAR_RANK) >= RANK_HARD {
        spawn_emitter(-32fx, 32fx, 0deg - 90deg, 0deg - s8, gap, count, FAN_SLOT_BASE + 7 * FAN_STRIDE, 200);
    }
    if global(GVAR_RANK) == RANK_LUNATIC {
        spawn_emitter(80fx, 0fx, 0deg - 40deg, 0deg - s10, gap, count, FAN_SLOT_BASE + 8 * FAN_STRIDE, 200);
    }
    wait(150);
    // group 3 (source 993-1010): F0 = +-70deg, F1 = +-6deg;
    // Lunatic side emitter (-80,0) with F0 = -40deg, F1 = -10deg
    spawn_emitter(-128fx, 128fx, 70deg, s6, gap, count, FAN_SLOT_BASE + 9 * FAN_STRIDE, 400);
    if global(GVAR_RANK) >= RANK_HARD {
        spawn_emitter(32fx, 32fx, 70deg, s6, gap, count, FAN_SLOT_BASE + 10 * FAN_STRIDE, 200);
    }
    spawn_emitter(128fx, 128fx, 0deg - 70deg, 0deg - s6, gap, count, FAN_SLOT_BASE + 11 * FAN_STRIDE, 400);
    if global(GVAR_RANK) >= RANK_HARD {
        spawn_emitter(-32fx, 32fx, 0deg - 70deg, 0deg - s6, gap, count, FAN_SLOT_BASE + 12 * FAN_STRIDE, 200);
    }
    if global(GVAR_RANK) == RANK_LUNATIC {
        spawn_emitter(-80fx, 0fx, 0deg - 40deg, 0deg - s10, gap, count, FAN_SLOT_BASE + 13 * FAN_STRIDE, 200);
    }
    wait(150);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
